import nltk
# Download necessary NLTK data (if not already present)
nltk.download('punkt')
nltk.download('averaged_perceptron_tagger')
from collections import Counter

# Extra downloads for newer NLTK versions; harmless if unavailable
nltk.download('punkt_tab')
nltk.download('averaged_perceptron_tagger_eng')

def task_func(content):
    if not content:
        return {}

    try:
        tokens = nltk.word_tokenize(content)
    except LookupError:
        tokens = nltk.wordpunct_tokenize(content)

    if not tokens:
        return {}

    # Remove the last word-like token, not merely the final punctuation token.
    last_word_idx = None
    for i in range(len(tokens) - 1, -1, -1):
        if any(ch.isalnum() for ch in tokens[i]):
            last_word_idx = i
            break

    if last_word_idx is None:
        return {}

    remaining_tokens = tokens[:last_word_idx] + tokens[last_word_idx + 1:]
    if not remaining_tokens:
        return {}

    try:
        tagged_tokens = nltk.pos_tag(remaining_tokens)
    except LookupError:
        nltk.download('averaged_perceptron_tagger_eng')
        tagged_tokens = nltk.pos_tag(remaining_tokens)

    return dict(Counter(tag for _, tag in tagged_tokens))

