    for file_path in glob.glob(os.path.join(directory_path, '*.xlsx')):
        if os.path.basename(file_path).startswith('~$'):
            continue

        try:
            workbook = load_workbook(file_path)
        except Exception:
            continue

        try:
            changed = False
            replacement = '\\\\' + '"'

            for worksheet in workbook.worksheets:
                for row in worksheet.iter_rows():
                    for cell in row:
                        if cell.data_type == 'f':
                            continue

                        value = cell.value
                        if isinstance(value, str) and '"' in value:
                            new_value = value.replace('"', replacement)
                            if new_value != value:
                                cell.value = new_value
                                changed = True

            if changed:
                workbook.save(file_path)

            processed += 1
        except Exception:
            continue
        finally:
            try:
                workbook.close()
            except Exception:
                pass

    return processed

