import numpy as np
import secrets
import hashlib
import base64

def task_func(num, from_base, to_base, alphabet):
    if from_base < 2 or to_base < 2:
        raise ValueError("from_base and to_base must be at least 2")

    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
    if from_base > len(digits) or to_base > len(digits):
        raise ValueError("base too large to convert")

    if not isinstance(num, str) or num == "":
        raise ValueError("num must be a non-empty string")

    if not isinstance(alphabet, str):
        raise ValueError("alphabet must be a string")

    try:
        alphabet_bytes = alphabet.encode("ascii")
    except UnicodeEncodeError as exc:
        raise ValueError("alphabet must contain ASCII characters") from exc

    if len(alphabet_bytes) != 64 or len(set(alphabet_bytes)) != 64:
        raise ValueError("alphabet must be a string of 64 unique characters")

    def char_to_value(ch):
        if from_base <= 36:
            if "0" <= ch <= "9":
                value = ord(ch) - ord("0")
            else:
                up = ch.upper()
                if "A" <= up <= "Z":
                    value = ord(up) - ord("A") + 10
                else:
                    return None
            return value if value < from_base else None
        else:
            try:
                value = digits.index(ch)
            except ValueError:
                return None
            return value if value < from_base else None

    value = 0
    for ch in num:
        digit = char_to_value(ch)
        if digit is None:
            raise ValueError("num contains invalid characters for the specified base")
        value = value * from_base + digit

    if value == 0:
        converted = "0"
    else:
        out_digits = digits[:to_base]
        parts = []
        while value > 0:
            value, rem = divmod(value, to_base)
            parts.append(out_digits[rem])
        converted = "".join(reversed(parts))

    salt = secrets.token_hex(16)
    payload = f"{converted}:{salt}".encode("utf-8")
    digest = hashlib.sha256(payload).digest()

    standard_b64 = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    custom_b64 = base64.b64encode(digest).translate(
        bytes.maketrans(standard_b64, alphabet_bytes)
    ).decode("ascii")

    return custom_b64, salt

